import csv,json,hashlib,datetime,calendar
from pathlib import Path
raw=Path('taipower-solar-original.csv').read_bytes()
with open('taipower-solar-original.csv',encoding='utf-8-sig',newline='') as f:
    reader=csv.DictReader(f); headers=reader.fieldnames; allrows=list(reader)
keys={'Kaohsiung Training Institute':'taipower-kaohsiung-training-institute-solar','Lanyu Power Plant':'taipower-lanyu-power-plant-solar'}
rows=[]
for lineno,r in enumerate(allrows,2):
    key=next((k for k in keys if k in r[headers[2]]),None)
    if r[headers[0]]!='2026' or r[headers[1]] not in ['07','08','09'] or not key: continue
    y,m=int(r[headers[0]]),int(r[headers[1]])
    period=f'{y}-{m:02}'
    nxt=f'{y+1}-01-01' if m==12 else f'{y}-{m+1:02}-01'
    name=r[headers[2]]
    rows.append(dict(site_id=keys[key],site_name_source=name,site_name_en=name.split('/',1)[1],generation_type='solar_photovoltaic',country='Taiwan',period=period,interval='monthly',period_start=period+'-01T00:00:00+08:00',period_end_exclusive=nxt+'T00:00:00+08:00',timezone='Asia/Taipei',generation_kwh=float(r[headers[4]]),installed_capacity_kw=float(r[headers[3]]),source_average_daily_generation_per_capacity=float(r[headers[5]]),source_record_number=lineno))
rows.sort(key=lambda r:(r['site_id'],r['period']))
assert len(rows)==6 and len(set((r['site_id'],r['period']) for r in rows))==6
assert all('Solar Power Station' in r['site_name_en'] and r['generation_kwh']>=0 and r['installed_capacity_kw']>0 for r in rows)
attribution='Taiwan Power Company, 2026, Taiwan Power Company_Solar photovoltaic generation and average unit installation capacity daily generation statistics table (dataset 29938; source data version not stated). This open data is released under the Open Government Data License, version 1.0; use is permitted subject to its terms. https://data.gov.tw/license'
prov=dict(retrieved_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),publisher='Taiwan Power Company',source_page='https://data.gov.tw/en/datasets/29938',download_url='https://service.taipower.com.tw/data/opendata/apply/file/d693003/001.csv',license_name='Open Government Data License, version 1.0',license_url='https://data.gov.tw/license',attribution=attribution,raw_file='taipower-solar-original.csv',raw_sha256=hashlib.sha256(raw).hexdigest(),raw_bytes=len(raw),raw_records=len(allrows),source_portal_updated_time='2026-06-02 00:47 (portal metadata; not actual data coverage endpoint)',download_http_last_modified='Tue, 20 Oct 2026 03:20:48 GMT',latest_actual_source_period='2026-09',normalized_file='taipower-solar-monthly-normalized.json',normalized_rows=len(rows),selection='Two named solar PV stations; latest three actual source months July-September 2026.',field_mappings=dict(period=[headers[0],headers[1]],site_name_source=headers[2],installed_capacity_kw=headers[3],generation_kwh=headers[4],source_average_daily_generation_per_capacity=headers[5]),interpretation=dict(generation='Reported actual monthly solar generation kWh, copied without scaling or power integration. Primary official statistics, not modelled potential.',capacity='Source installed capacity unit is kW, NOT kWp. Value preserved per month.',interval='CSV year/month identifies monthly energy totals. Title mentions daily because last column is an average daily per-capacity statistic, not the energy total.',timezone='Asia/Taipei is a geographic normalization convention requested for Taiwan calendar months. Source page/CSV does not explicitly declare timezone. Offset +08:00 boundaries were constructed, not copied source timestamps.',period_end='Exclusive first day of next calendar month; constructed boundary, not measured timestamp.',source_average_daily_generation_per_capacity='Supplementary source statistic copied as reported. Header does not explicitly label unit. Likely kWh/kW/day is inference only; NOT a measured daily kWh record and not used to derive energy.',site_identity='Solar PV stations only, including solar arrays hosted at other facilities. Lanyu Power Plant Solar Power Station is its named solar installation, not all host-plant generation.',missing='No missing/nonnumeric energy or capacity values in selected records. No imputation, date-shifting, interpolation or rescaling.',source_record_number='1-based CSV record number, header is record 1; not physical line number if quoted multiline fields occur.'),checks=dict(selected_rows=6,sites=2,months=['2026-07','2026-08','2026-09'],unique_site_months=6),limitations=['Gross-versus-net generation and meter calibration/settlement audit not verified.','Timezone is normalization convention, not source assertion.','No relationship to Maharashtra, Mira Road, local housing societies or resident consumption.'])
Path('taipower-solar-monthly-normalized.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf-8')
Path('taipower-solar-provenance.json').write_text(json.dumps(prov,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({'rows':rows,'raw_records':len(allrows),'headers':headers,'sha256':prov['raw_sha256']},ensure_ascii=True,indent=2))
